facilityFormItem.valueChangedEventHandler:
console.log('valueChangedEventHandler. Старт события. ИД текущего инициатора = ' + formItem.value);
functions.addPerformingAction('ChangeInitiator');
var initiatorId = formItem.value || functions.getValues().Initiator;
console.log('valueChangedEventHandler. Получение с формы текущего инициатора. ИД текущего инициатора = ' + initiatorId);
if (initiatorId != null) {
  console.log('valueChangedEventHandler. Инициатор не пустой.');
  ESS.network.sendRequest(`/api/functions/GetInstructionWithLinkLNA?employeeId=${initiatorId}`)
  .then(function (instruction) {
    if (typeof instruction === "string") {
      if (instruction) {
        functions.setValue('Instruction', instruction);
        console.log('valueChangedEventHandler. Параметр Instruction установлен. instruction = ' + functions.getValues().Instruction);
      }
    } else {
      console.log('valueChangedEventHandler. Параметр Instruction не установлен. typeof instruction = ' + typeof instruction);
      console.log('valueChangedEventHandler. instruction = ' + instruction);
    }
  });
  functions.removeError(window.errorInitiator);
  ESS.network.sendRequest(`/api/functions/CheckEmployeeConsentSigned?employeeId=${initiatorId}`)
  .then(function (isConsentSigned) {
    console.log('valueChangedEventHandler. Результат проверки подписания согласия у инициатора = ' + isConsentSigned);
    if (isConsentSigned != true) {
      window.errorInitiator = functions.showError(ESS.L('@HRPROVACATIONS.FACILITIES_GETVACATION_CONSENT_ERROR'));
      functions.removePerformingAction();
    } else {
      var url = `/api/functions/GetAvailableDaysInfo?employeeId=${initiatorId}`
      ESS.network.sendRequest(url)
      .then(function (availableDaysInfo) {
        functions.setValue('AvailableDays', availableDaysInfo);
        functions.removePerformingAction();
      });
    }
  })
  .catch(function (error) {
    functions.removePerformingAction();
    ESS.toasts.showToast(error.message, 'danger', false);
  });
}
console.log('valueChangedEventHandler. Конец события. ИД текущего инициатора = ' + formItem.value);

var today = new Date();
var yesterday = new Date(today);
yesterday.setDate(today.getDate() -1);
var beginDateValue = formItem.value;
var dateFromControl = new Date(beginDateValue).getTime();
functions.removeError(window.errorDateAnnual);
if (dateFromControl < yesterday.getTime()) {
  window.errorDateAnnual = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
}
window.setEndDateAnnual();

var initiatorId = functions.getValues().Initiator;
var vacationTypeId = functions.getValues().VacationTypeAnnual;
var beginDate = functions.getValues().BeginDateAnnual;
var url = `/api/functions/NNCheckVacationHasHoliday?periodBegin=${beginDate}&periodEnd=${formItem.value}&employeeId=${initiatorId}&vacationTypeId=${vacationTypeId}`;
ESS.network.sendRequest(url).then(function (warning){
  if(warning.length > 0)
    ESS.toasts.showToast(warning, 'warning', true);
});

var endDateValue = formItem.value;
var rows = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'];
if (rows.length > 0) {
  var rowIndex = rows[0].rowIndex;
  var endDate = new Date(endDateValue);
  var beginDate = new Date(endDate);
  beginDate.setDate(endDate.getDate() + 1);
  functions.setValue('VacationType&BeginDate&Duration&EndDateGrid', beginDate, rowIndex, 'BeginDate');
}

facilityFormItem.itemAddedEventHandler:
var rows = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'];
if (rows.length > 0) {
  var currIndex = rows.length - 1;
  var predIndex = currIndex - 1;
  var rowIndex = rows[currIndex].rowIndex;
  var endDateValue = rows.length == 1 ? functions.getValues().EndDateAnnual : rows[predIndex].rowValues.EndDate;
  if (!window.isEmpty(endDateValue))
  {
    var endDate = new Date(endDateValue);
    var beginDate = new Date(endDate);
    beginDate.setDate(endDate.getDate() + 1);
    functions.setValue('VacationType&BeginDate&Duration&EndDateGrid', beginDate, rowIndex, 'BeginDate');
  }
}

facilityFormItem.itemRemovingEventHandler:
var rows = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'];
if (rows.length > 1) {
  var currRow = rows.find(function (x) {
    return x.rowIndex === formItem.index;
  });
  var currIndex = rows.indexOf(currRow);
  var predIndex = currIndex - 1;
  var nextIndex = currIndex + 1;
  if (nextIndex < rows.length) {
    var rowIndex = rows[nextIndex].rowIndex;
    var endDateValue = currIndex == 0 ? functions.getValues().EndDateAnnual : rows[predIndex].rowValues.EndDate;
    if (!window.isEmpty(endDateValue))
    {
      var endDate = new Date(endDateValue);
      var beginDate = new Date(endDate);
      beginDate.setDate(endDate.getDate() + 1);
      functions.setValue('VacationType&BeginDate&Duration&EndDateGrid', beginDate, rowIndex, 'BeginDate');
    }
  }
}

resolve();

