facilityFormItem.onClickEventHandler:

var initiatorId = functions.getValues().Initiator;
var vacationStartDate = functions.getValues().BeginDateAnnual;
var vacationEndDate = functions.getValues().EndDateAnnual;

if (!initiatorId || !vacationStartDate || !vacationEndDate) {
  ESS.toasts.showToast(ESS.L('@HRPROVACATIONS.FACILITIES_NN_SUBSTITUTION_SETUP_ERROR_MISSING_DATA'), 'warning', true);
  return;
}

functions.setIsItemHidden('ShowSubstitutesButton', false);
functions.setIsItemHidden('SubstitutionsInfoBlock', true);

window.prepareSubstitutionParameters();

var substituteIdsString = functions.getValues().SubstituteIdsString;
var systemIdsString = functions.getValues().SystemIdsString;
var startDatesString = functions.getValues().StartDatesString;
var endDatesString = functions.getValues().EndDatesString;
var vacationTypeIdsString = functions.getValues().VacationTypeIdsString || '';

ESS.actions.facilityActions.runFacility(
  {
    id: '2a5f2cfc-8646-4bb8-920c-a985b15da804' 
  },
  {
    parameters: {
      InitiatorId: initiatorId,
      VacationStartDate: vacationStartDate,
      VacationEndDate: vacationEndDate,
      SubstituteIdsString: substituteIdsString,
      SystemIdsString: systemIdsString,
      StartDatesString: startDatesString,
      EndDatesString: endDatesString,
      VacationTypeIdsString: vacationTypeIdsString
    }
  }
);

facility.openingEventHandler:
  if (window.isFacilityRunning ?? false) {
    reject();
  }
  else {
    window.isFacilityRunning = true;
    var initiatorId = functions.getValues().Initiator;
    console.log('openingEventHandler. Старт события. ИД текущего инициатора = ' + initiatorId);
    ESS.network.sendRequest(`/api/functions/GetInitiatorId`)
    .then(function (initiatorId){
      ESS.network.sendRequest(`/api/functions/GetEmployeeCertificates`)
      .then(function (certs) {
        if (certs.length == 0) {
          ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_SENDSTATEMENT_NO_CERTIFICATES_ERROR'));
          reject();
        } else {
          ESS.network.sendRequest(`/api/functions/GetPostListByPerson`)
            .then(function (employee){
              ESS.network.sendRequest(`/api/functions/CheckEmployeeConsentSigned`)
                .then(function (isConsentSigned) {
                  console.log('openingEventHandler. Проверка подписания согласия = ' + isConsentSigned);
                  if (isConsentSigned != true && employee.positions.length == 1) {
                    ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), ESS.L('@HRPROVACATIONS.FACILITIES_GETVACATION_CONSENT_ERROR'));
                    reject();                    
                  }
                  else
                  {
                    console.log('openingEventHandler. Заполнение параметров услуги по умолчанию.');
                    ESS.network.sendRequest(`/api/functions/GetVacationStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=false`)
                    .then(function (VacationStatementData) {
                      if (VacationStatementData.Error.length == 0) {
                        if (employee.positions.length == 1) {
                          functions.setValue('Initiator', initiatorId);
                        }
                        console.log('openingEventHandler. Получение ИД инициатора. ИД = ' + initiatorId);
                        var templateId = JSON.parse(VacationStatementData.TemplateId);
                        var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
                        functions.setValue('TemplateId', templateId);
                        functions.setValue('DocumentKindId', docKindId);
                        functions.setValue('IsFromEssAccount', true);
                        // HACK. Убрана установка значения для инициатора по рекомендации HR PRO.
                        //functions.setValue('Initiator', initiatorId);
                        var url = `/api/functions/GetAvailableDaysInfo?employeeId=${functions.getValues().Initiator}`
                        ESS.network.sendRequest(url)
                        .then(function (availableDaysInfo) {
                          functions.setValue('AvailableDays', availableDaysInfo);
                        });

						var rows = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'];
                        rows.forEach(row => {
                          var rowIndex = row.rowIndex;
                          functions.removeItem('VacationType&BeginDate&Duration&EndDateGrid', rowIndex);
                        });

                        ESS.network.sendRequest(`/api/functions/GetInstructionWithLinkLNA?employeeId=${initiatorId}`)
                        .then(function (instruction) {
                          if (typeof instruction === "string") {
                            if (instruction) {
                              functions.setValue('Instruction', instruction);
                              console.log('openingEventHandler. Параметр Instruction установлен. instruction = ' + functions.getValues().Instruction);
                            }
                          } else {
                            console.log('openingEventHandler. Параметр Instruction не установлен. typeof instruction = ' + typeof instruction);
                            console.log('openingEventHandler. instruction = ' + instruction);
                          }
                        });
                        ESS.network.sendRequest(`/api/functions/GetVacationTypes?vacationKind=AnnualLeave`)
                        .then(function (annualVacationTypes) {
                          if (annualVacationTypes.length == 1) {
                            functions.setValue('VacationTypeAnnual', annualVacationTypes[0]['Id']);
                          }
                        });
                        resolve();
                        console.log('openingEventHandler. Конец события. ИД инициатора в услуге = ' + functions.getValues().Initiator);
                      } else {
                        ESS.dialogs.showMessageBox(ESS.L('@HRPROVACATIONS.ERROR_COMMON'), VacationStatementData.Error);
                      }
                    })
                    .catch(function (error) {
                      ESS.toasts.showToast(error.message, 'danger', false);
                    });
                  }
                })
                .catch(function (error) {
                  ESS.toasts.showToast(error.message, 'danger', false);
                });
              })
              .catch(function (error) {
                ESS.toasts.showToast(error.message, 'danger', false);
              });
            }
          })
        });
  }

facility.openedEventHandler:

console.log('openedEventHandler. Старт события. ИД текущего инициатора = ' + functions.getValues().Initiator);
window.isEmpty = function (value) {
  return (value == null || value.length === 0);
}

window.setEndDateAnnual = function () {
  var initiatorId = functions.getValues().Initiator;
  var vacationTypeId = functions.getValues().VacationTypeAnnual;
  var beginDate = functions.getValues().BeginDateAnnual;
  var duration = functions.getValues().DurationAnnual;
  if (duration != null && beginDate != null) {
    ESS.network.sendRequest(`/api/functions/NNGetVacationEndDate?dateBegin=${beginDate}&duration=${duration}&userId=${initiatorId}&vacationTypeId=${vacationTypeId}`)
    .then(function (newEndDateValue) {
      functions.setValue('EndDateAnnual', newEndDateValue);
    });
  }
}

window.setEndDate = function (rowIndex) {
  var initiatorId = functions.getValues().Initiator;
  var vacationTypeId = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'].find(function (x) {
    return x.rowIndex === rowIndex;
  }).rowValues['VacationType'];
  var beginDateValue = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'].find(function (x) {
    return x.rowIndex === rowIndex;
  }).rowValues['BeginDate'];
  var durationValue = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'].find(function (x) {
    return x.rowIndex === rowIndex;
  }).rowValues['Duration'];

  if (durationValue != null && beginDateValue != null) {
    ESS.network.sendRequest(`/api/functions/NNGetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${initiatorId}&vacationTypeId=${vacationTypeId}`)
    .then(function (newEndDateValue) {
      functions.setValue('VacationType&BeginDate&Duration&EndDateGrid', newEndDateValue, rowIndex, 'EndDate');
    });
  };
}      
window.getSubstitutionDataFromStorage = function() {
  try {
    var storedData = localStorage.getItem('NNSubstitutionSetup_Data');

    if (!storedData || storedData === '' || storedData === 'null') {
      console.log('[getSubstitutionDataFromStorage] No data in localStorage');
      return null;
    }

    var data = JSON.parse(storedData);

    if (!data.SubstituteIdsString || data.SubstituteIdsString === '') {
      console.log('[getSubstitutionDataFromStorage] No substitute IDs');
      return null;
    }

    var result = {
      substituteIds: data.SubstituteIdsString.split(';').filter(function(id) { return id && id !== ''; }),
      substituteNames: data.SubstituteNamesString ? data.SubstituteNamesString.split(';') : [],
      systemIds: data.SystemIdsString.split(';').filter(function(id) { return id && id !== ''; }),
      systemNames: data.SystemNamesString ? data.SystemNamesString.split(';') : [],
      startDates: data.StartDatesString.split(';').filter(function(date) { return date && date !== ''; }),
      endDates: data.EndDatesString.split(';').filter(function(date) { return date && date !== ''; }),
      vacationTypeIds: data.VacationTypeIdsString ? data.VacationTypeIdsString.split(';').filter(function(id) { return id && id !== ''; }) : []
    };

    console.log('[getSubstitutionDataFromStorage] Data loaded:', result.substituteIds.length, 'substitutes');
    return result;
  }
  catch (e) {
    console.error('[getSubstitutionDataFromStorage] Parse error:', e);
    return null;
  }
};

window.showSubstitutionInfo = function() {
  var data = window.getSubstitutionDataFromStorage();

  if (!data || data.substituteIds.length === 0) {
    console.log('[showSubstitutionInfo] No data to display');
    functions.setIsItemHidden('SubstitutionsInfoBlock', true);
    functions.setIsItemHidden('ShowSubstitutesButton', true);
    functions.setValue('SubstitutionsInfo', '');
    return false;
  }

  var infoText = ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_HEADER')) + '<br/><br/>';

  for (var i = 0; i < data.substituteIds.length; i++) {
    var startDate = data.startDates[i] ? new Date(data.startDates[i]).toLocaleDateString('ru-RU') : '?';
    var endDate = data.endDates[i] ? new Date(data.endDates[i]).toLocaleDateString('ru-RU') : '?';
    var subName = data.substituteNames[i];
    var sysName = data.systemNames[i];

    infoText += ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_ITEM_TEMPLATE'),(i + 1), subName, sysName , startDate, endDate) + '<br/>';
  }

  functions.setValue('SubstitutionsInfo', infoText);
  functions.setIsItemHidden('SubstitutionsInfoBlock', false);
  functions.setIsItemHidden('ShowSubstitutesButton', false);

  console.log('[showSubstitutionInfo] Info displayed');
  return true;
};

window.prepareSubstitutionParameters = function() {
  var data = window.getSubstitutionDataFromStorage();

  if (!data || data.substituteIds.length === 0) {
    console.log('[prepareSubstitutionParameters] No data to prepare');

    functions.setValue('SubstituteIdsString', '');
    functions.setValue('SystemIdsString', '');
    functions.setValue('StartDatesString', '');
    functions.setValue('EndDatesString', '');
    functions.setValue('VacationTypeIdsString', '');

    return false;
  }

  functions.setValue('SubstituteIdsString', data.substituteIds.join(';'));
  functions.setValue('SystemIdsString', data.systemIds.join(';'));
  functions.setValue('StartDatesString', data.startDates.join(';'));
  functions.setValue('EndDatesString', data.endDates.join(';'));
  functions.setValue('VacationTypeIdsString', data.vacationTypeIds ? data.vacationTypeIds.join(';') : '');

  console.log('[prepareSubstitutionParameters] Parameters set:', data.substituteIds.length, 'substitutes');
  return true;
};

console.log('openedEventHandler. Конец события. ИД текущего инициатора = ' + functions.getValues().Initiator);

facility.beforeSubmitEventHandler:
console.log('beforeSubmitEventHandler. Старт события.');
console.log('beforeSubmitEventHandler. functions.getValues() = ');
console.log(JSON.stringify(functions.getValues()));

window.prepareSubstitutionParameters();

var initiatorId = functions.getValues().Initiator;
var documentKindId = functions.getValues().DocumentKindId;
var vacationTypeId = functions.getValues().VacationTypeAnnual;
var beginDate = functions.getValues().BeginDateAnnual;
var endDate = functions.getValues().EndDateAnnual;
var duration = functions.getValues().DurationAnnual;
var rows = functions.getValues()['VacationType&BeginDate&Duration&EndDateGrid'];
var vacationTypeIdsArray = [];
var beginDateArray = [];
var endDateArray = [];
var durationArray = [];
rows.forEach(row => {
  if (row.rowValues.VacationType != null && row.rowValues.BeginDate != null && row.rowValues.EndDate && row.rowValues.Duration) {
    vacationTypeIdsArray.push(row.rowValues.VacationType);
    var beginDate = row.rowValues.BeginDate;
    beginDateArray.push(beginDate);
    durationArray.push(row.rowValues.Duration);
    var endDate = row.rowValues.EndDate;
    endDateArray.push(endDate);
  };
});

var body = JSON.stringify({
  employeeId : new Number(initiatorId),
  vacationTypeIds : vacationTypeIdsArray,
  beginDates : beginDateArray,
  endDates : endDateArray,
  durations : durationArray
});

var getAttachableVacationsInfo = ESS.network.sendRequest('/api/functions/GetAttachableVacationsInfo', { body: body, method: 'POST' })
.then(function (attachableVacationsInfo) {
  functions.setValue('Field_Доп отпуска', attachableVacationsInfo);
  var durationFromControl = functions.getValues().DurationAnnual;
  functions.setValue('Field_Продолжительность_отпуска', durationFromControl);
  var beginDate = JSON.stringify(new Date(functions.getValues().BeginDateAnnual).toLocaleDateString('en-CA'));
  var endDate = JSON.stringify(new Date(functions.getValues().EndDateAnnual).toLocaleDateString('en-CA'));
  var dates = [];
  dates.push(beginDate);
  dates.push(endDate);
  ESS.network.sendRequest(`/api/functions/GetFormatDates?employeeId=${initiatorId}&dates=[${dates}]`)
  .then(function (dates) {
    functions.setValue('Field_Дата_начала_отпуска', dates[0]);
    functions.setValue('Field_Дата_окончания_отпуска', dates[1]);
  });
})
.catch(function (error) {
  ESS.toasts.showToast(error.message, 'danger', false);
  reject();
});

// Добавить основной отпуск к списку.
vacationTypeIdsArray.push(vacationTypeId);
beginDateArray.push(beginDate);
durationArray.push(duration);
endDateArray.push(endDate);
var validateVacationData = ESS.scripts.HRProVacations.validateVacationData({ functions, initiatorId, documentKindId, statementId: 0, vacationTypeIdsArray, beginDateArray, endDateArray, durationArray });

var validateSubstitutionDates = function() {
  var substitutionsInfo = functions.getValues().SubstitutionsInfo;

  if (!substitutionsInfo || substitutionsInfo === '' || substitutionsInfo === 'null') {
    return Promise.resolve({ isValid: true, errors: [] });
  }

  var vacationPeriodsJson = '';
  if (beginDate && endDate) {
    var periods = [{ StartDate: beginDate, EndDate: endDate }];
    vacationPeriodsJson = JSON.stringify(periods);
  }

  return ESS.scripts.HRProVacations.validateSubstitutionDates({ VacationPeriodsJson: vacationPeriodsJson, StartDatesString: functions.getValues().StartDatesString || '', EndDatesString: functions.getValues().EndDatesString || '', IsCallingService: true });
};

console.log('beforeSubmitEventHandler. Начало выполнения запросов getAttachableVacationsInfo, validateVacationData, validateSubstitutionDates. initiatorId = ' + initiatorId + '. documentKindId = ' + documentKindId);

Promise.all([getAttachableVacationsInfo, validateVacationData, validateSubstitutionDates()])
.then(function(results) {
  var substitutionResult = results[2];
  if (substitutionResult && !substitutionResult.isValid) {
    if (substitutionResult.errors && substitutionResult.errors.length > 0) {
      ESS.toasts.showToast(substitutionResult.errors[0].message, 'danger', true);
    }
    reject();
    return;
  }
  console.log('beforeSubmitEventHandler. Успешное завершение события.');
  resolve();
})
.catch(function(error) {
  console.log('beforeSubmitEventHandler. Завершение события с ошибкой.');
  reject();
});

facility.closedEventHandler:
window.isFacilityRunning = false;

localStorage.removeItem('NNSubstitutionSetup_Data');

if (sender.performingAction === 'SUBMIT_FACILITY_PARAMETERS') 
{
  ESS.closeElement(sender.parent); 
  ESS.widgets.updateWidgets();
}
delete window.isEmpty;
